package handlers.skill.effects;

import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.entity.item.instance.Item;
import org.l2jmobius.gameserver.mechanics.effects.AbstractEffect;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * Handles the logic for the {@code Ride} skill effect.<br>
 * This class manages how a creature interacts with mounts or vehicles during travel.
 * @author Liamxroy
 */
public class Ride extends AbstractEffect
{
	private final int _npcId;
	
	/**
	 * Creates a new {@code Ride} effect.<br>
	 * This constructor initializes the effect using provided statistics.
	 * @param params A {@code StatSet} containing the configuration data.
	 */
	public Ride(StatSet params)
	{
		_npcId = params.getInt("npcId", 0);
	}
	
	/**
	 * Checks if the effect occurs immediately.<br>
	 * This method always returns {@code true}.
	 * @return {@code true} if the effect is instant.
	 */
	@Override
	public boolean isInstant()
	{
		return true;
	}
	
	/**
	 * Executes an instant effect on a target creature.<br>
	 * This method mounts the player onto a specific NPC.<br>
	 * It checks if the target is a player before applying the effect.
	 * @param effector The creature performing the action.
	 * @param effected The creature receiving the effect.
	 * @param skill The {@code Skill} used to trigger this effect.
	 * @param item The {@code Item} associated with the effect.
	 */
	@Override
	public void instant(Creature effector, Creature effected, Skill skill, Item item)
	{
		if (!effected.isPlayer())
		{
			return;
		}
		
		effected.asPlayer().mount(_npcId, 0, false);
	}
}
